using System;
using System.IO;
using System.Globalization;
using Por.Core;

// Independently authored supervisor checks, not generated by Qwen.
internal static class Program
{
    static int checks;
    static void Equal<T>(T expected, T actual, string label)
    {
        checks++;
        if (!object.Equals(expected,actual)) throw new Exception(label+": expected "+expected+", got "+actual);
    }
    static void Main(string[] args)
    {
        checks += PortVerification.ConstantChecks.Run(Path.Combine(AppContext.BaseDirectory,"../../../../../evidence/constant-vectors.tsv"));
        checks += PortVerification.RulesChecks.Run();
        CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo("ar-SA");
        Equal("-2147483648",StrUtil.NumStr(int.MinValue),"decimal int min");
        Equal("2147483647",StrUtil.NumStr(int.MaxValue),"decimal int max");
        for(int n=0;n<65536;n++) Equal((n%100).ToString("D2",CultureInfo.InvariantCulture),StrUtil.ZeroPad2((ushort)n),"zero pad "+n);
        foreach(string text in new[]{"", "a", "abcdef", "  X  "})
        for(int w=0;w<256;w++)
        {
            string clipped=text.Substring(0,Math.Min(text.Length,w));
            Equal(clipped+new string(' ',w-clipped.Length),StrUtil.PadRight(text,(byte)w),"pad right");
            Equal(new string(' ',w-clipped.Length)+clipped,StrUtil.PadLeft(text,(byte)w),"pad left");
        }
        string vector=Path.Combine(AppContext.BaseDirectory,"../../../../../evidence/dax-vectors.bin");
        if(args.Length>0)vector=args[0];
        using(var reader = new BinaryReader(File.OpenRead(vector)))
        {
            while(reader.BaseStream.Position<reader.BaseStream.Length)
            {
                int len=BigInt(reader),size=BigInt(reader);
                byte[] input=reader.ReadBytes(len),expected=reader.ReadBytes(size),copy=(byte[])input.Clone();
                byte[] actual=DaxIo.DecompressDax(input,size);
                Equal(size,actual.Length,"DAX length");
                for(int i=0;i<size;i++) Equal(expected[i],actual[i],"DAX byte");
                for(int i=0;i<len;i++) Equal(copy[i],input[i],"input immutable");
            }
        }
        string scratch=Path.Combine(Path.GetTempPath(),"por-port-test-"+Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(scratch);
        try
        {
            string file=Path.Combine(scratch,"record.dat");byte[] bytes={0,128,255,32};
            Equal(true,FileUtil.WriteRecord(file,bytes,4),"write record");
            byte[] target=new byte[4];Equal(true,FileUtil.ReadRecord(file,target,4),"read record");
            for(int i=0;i<4;i++)Equal(bytes[i],target[i],"record bytes");
            Equal(false,FileUtil.ReadRecord(file,new byte[3],3),"reject oversized file");
            Equal(false,FileUtil.ReadRecord(file,new byte[5],5),"reject short file");
            FileUtil.DeleteFile(file);Equal(false,File.Exists(file),"delete record");
            Equal(false,FileUtil.ReadRecord(file,new byte[4],4),"missing read");FileUtil.DeleteFile(file);
        }
        finally { Directory.Delete(scratch,true); }
        Console.WriteLine("PASS: "+checks+" independent assertions (text, DAX, file IO)");
    }
    static int BigInt(BinaryReader r)
    { return (r.ReadByte()<<24)|(r.ReadByte()<<16)|(r.ReadByte()<<8)|r.ReadByte(); }
}
